using Microsoft.Extensions.Localization;
using Tempo.Blazor.Localization;
using Tempo.Blazor.Resources;

/// <summary>
/// Override specific keys while delegating the rest to the built-in .resx resources.
/// Useful when you only need to tweak a few labels without reimplementing everything.
/// </summary>
public class PartialOverrideLocalizer : ITmLocalizer
{
    private readonly IStringLocalizer<TmResources> _builtIn;

    private readonly Dictionary<string, string> _overrides = new()
    {
        ["Tm_Save"] = "Save & Close",
        ["TmDataTable_NoResults"] = "Nothing here yet.",
        ["TmDataTable_SearchPlaceholder"] = "Type to search...",
    };

    public PartialOverrideLocalizer(IStringLocalizer<TmResources> builtIn)
    {
        _builtIn = builtIn;
    }

    public string this[string key] =>
        _overrides.TryGetValue(key, out var v) ? v : _builtIn[key].Value;

    public string this[string key, params object[] arguments] =>
        _overrides.TryGetValue(key, out var v)
            ? string.Format(v, arguments)
            : _builtIn[key, arguments].Value;
}

