    private string _currentCulture = System.Globalization.CultureInfo.CurrentUICulture.Name;

    private List<SelectOption<string>> _cultureOptions = new()
    {
        new("en", "English"),
        new("cs", "Čeština")
    };

    private void ChangeCulture(string culture)
    {
        var cultureInfo = new System.Globalization.CultureInfo(culture);
        System.Globalization.CultureInfo.DefaultThreadCurrentCulture = cultureInfo;
        System.Globalization.CultureInfo.DefaultThreadCurrentUICulture = cultureInfo;

        // Force full reload so all components re-resolve their localized strings
        Nav.NavigateTo(Nav.Uri, forceLoad: true);
    }
}

